CREATE OR REPLACE FUNCTION trip_private.confirm_game_nights(p_trip uuid,p_option integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_start timestamptz; v_trip date; v_zone text; v_host uuid; v_count integer; v_local timestamp; v_occurrence timestamptz; BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can confirm'; END IF; SELECT (options->>p_option)::timestamptz INTO v_start FROM public.game_night_polls WHERE trip_id=p_trip AND confirmed_option IS NULL; IF v_start IS NULL OR v_start <= now() THEN RAISE EXCEPTION 'Choose a future option'; END IF; SELECT start_date,home_timezone INTO v_trip,v_zone FROM public.trips WHERE id=p_trip; v_local:=v_start AT TIME ZONE v_zone; IF v_local::date >= v_trip THEN RAISE EXCEPTION 'Time must be before the trip'; END IF; SELECT count(*) INTO v_count FROM public.trip_members WHERE trip_id=p_trip; IF v_count=0 THEN RAISE EXCEPTION 'Trip has no members'; END IF; DELETE FROM public.game_nights WHERE trip_id=p_trip; FOR i IN 1..104 LOOP v_occurrence:=(v_local + ((i-1)* interval '7 days')) AT TIME ZONE v_zone; EXIT WHEN (v_occurrence AT TIME ZONE v_zone)::date >= v_trip; SELECT user_id INTO v_host FROM public.trip_members WHERE trip_id=p_trip ORDER BY joined_at,user_id LIMIT 1 OFFSET ((i-1)%v_count); INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,i,v_occurrence,v_host); END LOOP; UPDATE public.game_night_polls SET confirmed_option=p_option WHERE trip_id=p_trip; END $fn$;